const items = $input.all();
const out = [];
for (const it of items) {
  const j = it.json;
  const isErrorTrigger = !!(j.execution && j.workflow);
  let workflowName, nodeName, message;
  if (isErrorTrigger) {
    workflowName = j.workflow ? j.workflow.name : 'CA Firm Automation';
    nodeName = j.execution && j.execution.lastNodeExecuted ? j.execution.lastNodeExecuted : 'unknown';
    message = j.execution && j.execution.error ? j.execution.error.message : 'Unknown error (workflow-level trigger)';
  } else {
    workflowName = 'CA Firm Automation';
    nodeName = j.node_name_hint || $input.first().json.__nodeHint || 'branch node';
    message = (j.error && j.error.message) ? j.error.message :
               (j.message ? j.message : JSON.stringify(j).slice(0, 500));
  }
  out.push({
    json: {
      error_id: 'ERR-' + Date.now() + '-' + Math.floor(Math.random()*1000),
      workflow_name: workflowName,
      node_name: nodeName,
      error_message: String(message).slice(0, 900),
      timestamp: new Date().toISOString()
    }
  });
}
return out;

const body = $json.body || {};
const entry = (body.entry && body.entry[0]) || {};
const change = (entry.changes && entry.changes[0]) || {};
const value = change.value || {};
const messages = value.messages || [];
const contacts = value.contacts || [];

if (!messages.length) {
  return [{ json: { has_message: false } }];
}

const msg = messages[0];
const contact = contacts[0] || {};
const from = msg.from || '';
const msgType = msg.type || 'text';
let textBody = '', mediaId = '', mediaCaption = '', mediaFilename = '';

if (msgType === 'text') {
  textBody = (msg.text && msg.text.body) || '';
} else if (msgType === 'image') {
  mediaId = (msg.image && msg.image.id) || '';
  mediaCaption = (msg.image && msg.image.caption) || '';
} else if (msgType === 'document') {
  mediaId = (msg.document && msg.document.id) || '';
  mediaCaption = (msg.document && msg.document.caption) || '';
  mediaFilename = (msg.document && msg.document.filename) || '';
} else if (msgType === 'audio' || msgType === 'video' || msgType === 'sticker') {
  mediaId = (msg[msgType] && msg[msgType].id) || '';
}

return [{
  json: {
    has_message: true,
    is_media: (msgType !== 'text'),
    from_phone: from,
    contact_name: (contact.profile && contact.profile.name) || '',
    message_type: msgType,
    message_text: textBody,
    media_id: mediaId,
    media_caption: mediaCaption,
    media_filename: mediaFilename,
    received_at: new Date().toISOString()
  }
}];

const incoming = $('WhatsApp • Parse Incoming Message').first().json;
const fromPhone = String(incoming.from_phone || '').replace(/\D/g, '');
const rows = $input.all();
let matched = null;
for (const r of rows) {
  const p = String(r.json.phone || '').replace(/\D/g, '');
  if (p && fromPhone && (p === fromPhone || p.endsWith(fromPhone) || fromPhone.endsWith(p))) {
    matched = r.json;
    break;
  }
}
return [{
  json: {
    ...incoming,
    client_found: !!matched,
    client_id: matched ? matched.client_id : '',
    client_name: matched ? matched.name : (incoming.contact_name || 'there'),
    client_email: matched ? matched.email : ''
  }
}];

const client = $('Data • Match Client by Phone').first().json;
const complianceRows = $('Data • Get Compliance Context (WA)').all().map(r => r.json)
  .filter(r => r.client_id === client.client_id);
const docRows = $('Data • Get Documents Context (WA)').all().map(r => r.json)
  .filter(r => r.client_id === client.client_id);

const complianceLines = complianceRows.length
  ? complianceRows.map(r => `- ${r.compliance_type}: due ${r.due_date}, status ${r.status}`).join('\n')
  : '- No compliance records on file.';

const docLines = docRows.length
  ? docRows.map(r => `- ${r.document_name} (${r.compliance_type}): ${r.status}`).join('\n')
  : '- No documents currently requested.';

const systemContext = `You are the AI support assistant for ${$vars && $vars.FIRM_NAME ? $vars.FIRM_NAME : 'the CA firm'} (a Chartered Accountancy firm in India). Today's date is ${$now.toFormat('dd LLL yyyy')}.
Client: ${client.client_name} (Client ID: ${client.client_id || 'N/A'}).

Client's compliance calendar:
${complianceLines}

Client's document status:
${docLines}

Rules:
- Answer questions about GST, ITR, TDS, ROC, and general tax/compliance in simple, clear language (Hindi-English mix is fine if the client writes that way).
- Use the compliance/document data above to answer specifics about THIS client's due dates and pending documents. Never invent a due date or document status that isn't listed above.
- For anything requiring judgment calls, specific tax advice beyond general FAQ, or anything you are not fully certain about, tell the client a CA from the team will personally follow up, and do not guess.
- Keep replies short and WhatsApp-appropriate (a few lines max).
- Never share other clients' data.`;

return [{
  json: {
    system_context: systemContext,
    user_message: client.message_text,
    from_phone: client.from_phone,
    client_id: client.client_id,
    client_name: client.client_name
  }
}];

const client = $('Data • Match Client by Phone').first().json;
const rows = $input.all().map(r => r.json).filter(r => r.client_id === client.client_id && r.status === 'Pending');
const doc = rows[0] || null;
return [{
  json: {
    from_phone: client.from_phone,
    client_name: client.client_name,
    matched: !!doc,
    doc_id: doc ? doc.doc_id : '',
    document_name: doc ? doc.document_name : '',
    compliance_type: doc ? doc.compliance_type : '',
    client_id: client.client_id,
  }
}];

const c = $('Data • Match Client by Phone').first().json;
return [{
  json: {
    lead_id: 'LEAD-WA-' + Date.now(),
    name: c.contact_name || 'WhatsApp Lead',
    phone: c.from_phone,
    email: '',
    source: 'WhatsApp',
    requirement: '',
    business_type: '',
    urgency: '',
    qualification_score: '',
    status: 'New',
    followup_date: $now.plus({ days: 2 }).toFormat('yyyy-MM-dd'),
    followup_attempts: 0,
    created_at: $now.toISO(),
    notes: '',
    message_text: c.message_text
  }
}];

