parameters.jsCode:
let raw = ($json.text || $json.response?.text || $json.output || '').toString();
raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
let parsed = {};
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) {
  parsed = { requirement: 'Unclear', business_type: 'Unclear', urgency: 'Unclear', score: 'Warm' };
}
