const j = $json;
const headers = j.payload && j.payload.headers ? j.payload.headers : [];
const fromHeader = (headers.find(h => h.name === 'From') || {}).value || j.from || '';
const subjectHeader = (headers.find(h => h.name === 'Subject') || {}).value || j.subject || '';
const emailMatch = fromHeader.match(/[\w.+-]+@[\w-]+\.[\w.-]+/);
