  }
}];

const b = $json.body || {};
const clientId = (b.client_id || '').toString().trim();
const complianceType = (b.compliance_type || 'General').toString().trim();
const documents = Array.isArray(b.documents) ? b.documents.filter(d => d && String(d).trim()) : [];
const valid = !!(clientId && documents.length);
return [{ json: { valid, client_id: clientId, compliance_type: complianceType, documents } }];

const req = $('Validate Document Request Payload').first().json;
const rows = $input.all().map(r => r.json);
const client = rows.find(r => r.client_id === req.client_id) || {};
return [{
