parameters.text:
=You are writing on behalf of {{ $vars.FIRM_NAME || 'Your CA Firm' }}, a Chartered Accountancy firm in India, to a client, asking them to submit documents needed for their {{ $json.compliance_type }} work. Write a short, polite, clear message (WhatsApp/email friendly, 4-6 lines) that lists the required documents and asks them to share it at the earliest so filing isn't delayed. Include this exact document list formatted as-is:
{{ $json.doc_list }}

Client name: {{ $json.client_name }}

parameters.jsCode:
const j = $json;
const text = j.text || j.response?.text || j.output || '';
return [{ json: { ...$('Build Document Request Message Data').first().json, message: text } }];

const b = $json.body || {};
const invoiceId = (b.invoice_id || '').toString().trim();
const amountPaid = b.amount_paid || b.amount || '';
const valid = !!invoiceId;
return [{ json: { valid, invoice_id: invoiceId, amount_paid: amountPaid, payment_date: b.payment_date || new Date().toISOString() } }];

const pay = $('Validate Payment Payload').first().json;
const rows = $input.all().map(r => r.json);
const inv = rows.find(r => r.invoice_id === pay.invoice_id);
if (!inv) {
  return [{ json: { found: false, invoice_id: pay.invoice_id } }];
}
return [{
  json: {
    found: true,
    invoice_id: inv.invoice_id,
    client_id: inv.client_id,
    client_name: inv.client_name,
    phone: inv.phone,
    email: inv.email,
    amount: inv.amount,
    currency: inv.currency || 'INR',
    due_date: inv.due_date,
    status: 'Paid',
    reminder_count: inv.reminder_count || 0,
    last_reminder_date: inv.last_reminder_date || '',
    escalated: inv.escalated || 'No',
    payment_date: pay.payment_date
  }
}];

const j = $json;
const text = j.text || j.response?.text || j.output || '';
return [{ json: { ...$('Match & Update Invoice').first().json, message: text } }];

const MS_DAY = 24 * 60 * 60 * 1000;
const todayStr = new Date().toISOString().slice(0, 10);
const today = new Date(todayStr + 'T00:00:00Z');

function daysDiff(dateStr) {
  if (!dateStr) return null;
  const d = new Date(String(dateStr).slice(0, 10) + 'T00:00:00Z');
  if (isNaN(d.getTime())) return null;
  return Math.round((d.getTime() - today.getTime()) / MS_DAY);
}

const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if (!r.due_date || r.status === 'Filed') continue;
  const days = daysDiff(r.due_date);
  if (days === null) continue;

  let stage = null;
  if (days === 7) stage = 'friendly_7d';
  else if (days === 3) stage = 'reminder_3d';
  else if (days === 1) stage = 'urgent_1d';
  else if (days === 0) stage = 'due_today';
  else if (days < 0) stage = 'overdue';

  if (!stage) continue;

  out.push({
    json: {
      compliance_id: r.compliance_id,
      client_id: r.client_id,
      client_name: r.client_name,
      phone: r.phone,
      email: r.email,
      compliance_type: r.compliance_type,
      due_date: r.due_date,
      status: r.status,
      reminder_count: Number(r.reminder_count || 0),
      days_until_due: days,
      days_overdue: days < 0 ? Math.abs(days) : 0,
      stage
    }
  });
}
return out;

parameters.text:
=Write a short WhatsApp/email-friendly compliance reminder (3-5 lines) from {{ $vars.FIRM_NAME || 'Your CA Firm' }}, a Chartered Accountancy firm in India, to a client.

Client: {{ $json.client_name }}
Compliance type: {{ $json.compliance_type }}
Due date: {{ $json.due_date }}
Stage: {{ $json.stage }} (friendly_7d = gentle heads-up, reminder_3d = clearer reminder, urgent_1d = urgent tone due tomorrow, due_today = due today act now, overdue = firm but polite, {{ $json.days_overdue }} days overdue, mention possible late fee/penalty risk)

Tone must match the stage exactly. Ask them to share any pending info/documents needed to file on time. Sign off simply as "Team".

parameters.jsCode:
const j = $json;
const text = j.text || j.response?.text || j.output || '';
return [{ json: { ...$('Compute Days Until Due & Filter').item.json, message: text } }];

const MS_DAY = 24 * 60 * 60 * 1000;
const now = new Date();

function daysSince(dateStr) {
  if (!dateStr) return null;
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return null;
  return Math.floor((now.getTime() - d.getTime()) / MS_DAY);
}

const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if (r.status !== 'Pending') continue;
  const refDate = r.last_followup_date || r.requested_date;
  const gap = daysSince(refDate);
  if (gap === null || gap < 3) continue;

  out.push({
    json: {
      doc_id: r.doc_id,
      client_id: r.client_id,
      client_name: r.client_name,
      phone: r.phone,
      email: r.email,
      compliance_type: r.compliance_type,
      document_name: r.document_name,
      requested_date: r.requested_date,
      followup_count: Number(r.followup_count || 0)
    }
  });
}
return out;

parameters.text:
=Write a short WhatsApp/email-friendly follow-up (3-4 lines) from {{ $vars.FIRM_NAME || 'Your CA Firm' }} reminding a client to share a still-pending document.

Client: {{ $json.client_name }}
Document: {{ $json.document_name }}
Related to: {{ $json.compliance_type }}
This is follow-up number: {{ $json.followup_count + 1 }} (1st = gentle, 2nd = clearer, 3rd+ = firmer, mention it may delay filing/compliance).

Ask them to share it at the earliest convenience.

parameters.jsCode:
const j = $json;
const text = j.text || j.response?.text || j.output || '';
return [{ json: { ...$('Compute Pending Docs Needing Followup').item.json, message: text } }];

const todayStr = new Date().toISOString().slice(0, 10);
const closedStatuses = ['Converted', 'Lost', 'Cold-Closed'];

const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if (closedStatuses.includes(r.status)) continue;
  if (!r.followup_date) continue;
  if (String(r.followup_date).slice(0, 10) > todayStr) continue;

  out.push({
    json: {
      lead_id: r.lead_id,
      name: r.name,
      phone: r.phone,
      email: r.email,
      requirement: r.requirement || 'their requirement',
      urgency: r.urgency || 'Unclear',
      status: r.status || 'New',
      followup_attempts: Number(r.followup_attempts || 0)
    }
  });
}
return out;

const j = $json;
const text = j.text || j.response?.text || j.output || '';
return [{ json: { ...$('Compute Leads Needing Followup').item.json, message: text } }];

const j = $json;
const attempts = j.followup_attempts + 1;
const maxReached = attempts >= 4;
const next = new Date();
next.setDate(next.getDate() + 3);
return [{
  json: {
    lead_id: j.lead_id,
    phone: j.phone,
    followup_attempts: attempts,
    followup_date: maxReached ? '' : next.toISOString().slice(0, 10),
    status: maxReached ? 'Cold-Closed' : j.status
  }
}];

const MS_DAY = 24 * 60 * 60 * 1000;
const todayStr = new Date().toISOString().slice(0, 10);
const today = new Date(todayStr + 'T00:00:00Z');

function daysDiff(dateStr) {
  if (!dateStr) return null;
  const d = new Date(String(dateStr).slice(0, 10) + 'T00:00:00Z');
  if (isNaN(d.getTime())) return null;
  return Math.round((today.getTime() - d.getTime()) / MS_DAY); // positive = overdue
}

const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if (r.status === 'Paid') continue;
  const overdueDays = daysDiff(r.due_date);
  if (overdueDays === null) continue;

  let stage = null;
  if (overdueDays === -3) stage = 'upcoming_3d';
  else if (overdueDays === 0) stage = 'due_today';
  else if (overdueDays >= 1 && overdueDays <= 7) stage = 'overdue_mild';
  else if (overdueDays >= 8 && overdueDays <= 15) stage = 'overdue_moderate';
  else if (overdueDays > 15) stage = 'overdue_severe';

  if (!stage) continue;

  out.push({
    json: {
      invoice_id: r.invoice_id,
      client_id: r.client_id,
      client_name: r.client_name,
      phone: r.phone,
      email: r.email,
      amount: r.amount,
      currency: r.currency || 'INR',
      due_date: r.due_date,
      reminder_count: Number(r.reminder_count || 0),
      escalated: r.escalated || 'No',
      days_overdue: overdueDays > 0 ? overdueDays : 0,
      stage
    }
  });
}
return out;

parameters.text:
=Write a short WhatsApp/email-friendly payment reminder (3-5 lines) from {{ $vars.FIRM_NAME || 'Your CA Firm' }}, a Chartered Accountancy firm in India.

Client: {{ $json.client_name }}
Invoice: {{ $json.invoice_id }}
Amount due: {{ $json.currency }} {{ $json.amount }}
Due date: {{ $json.due_date }}
Stage: {{ $json.stage }} (upcoming_3d = friendly heads-up, due_today = due today please pay, overdue_mild = polite overdue reminder up to a week, overdue_moderate = firmer tone 8-15 days overdue mention it's affecting the account, overdue_severe = firm professional tone, {{ $json.days_overdue }} days overdue, mention the team may follow up by call)

Match tone exactly to the stage. Include a simple payment request line. Do not be rude even at overdue_severe — stay professional.

parameters.jsCode:
const j = $json;
const text = j.text || j.response?.text || j.output || '';
return [{ json: { ...$('Compute Invoice Reminder Stage').item.json, message: text } }];

const j = $json;
const overdue = j.days_overdue > 0;
return [{
  json: {
    invoice_id: j.invoice_id,
    status: overdue ? 'Overdue' : 'Pending',
